":[[[[[[{"p":[{"t9":"We offer a variety of discounts. There are no discounts available at the BART vending machines. All discounts are set up in advance through Clipper. A little work up front helps you save money."}]},{"ul":[{"li":[{"g23":"Riders who use more than one transit agency in a single trip (e.g., BART to Muni) will only be charged full fare on the first operator. A transfer discount of up to $2.85 will apply on any additional transit agency the rider uses within a two-hour window. This discount is available when using Tap and Ride (contactless bank cards, Apple Pay and Google Pay) and Clipper card users once their cards has been upgraded to the new system, a process customers can initiate by logging into your account on the new account-based\nClipper website\n."},{"l5":"Clipper website"}]},{"li":[{"g24":"Low income adults earning 200% or less of the federal poverty level get 50% off through the regional\nClipper START program\n."},{"l6":"Clipper START program"}]},{"li":[{"g25":"Youth 5-18 years old get 50% off with a\nYouth Clipper card\n. 4 years and younger ride free. (Search for the various locations where you can apply and immediately receive a discount card by selecting \"Staffed Locations\" under \"Location Type\" for Youth and Senior card services. They are also available by mail)"},{"l7":"Youth Clipper card"}]},{"li":[{"g26":"Seniors 65 and over get 62.5% off with a\nSenior Clipper card\n. (Search for the various locations where you can apply and immediately receive a discount card by selecting \"Staffed Locations\" under \"Location Type\" for Youth and Senior card services. They are also available by mail)"},{"l8":"Senior Clipper card"}]},{"li":[{"g27":"The\nClipper Access card\n(formerly known as RTC) is a version of Clipper created for passengers under 65 with qualifying disabilities to provide 62.5% off."},{"l9":"Clipper Access card"}]},{"li":[{"g28":"BART offers a “High-value Discount.” Adult Clipper cards get a 6.25% discount on cash value rides by buying $48 worth of value for $45 or $64 worth of value for $60 when autoload is set up with your registered Clipper card. You can only purchase an HVD ticket\nonline by setting up Autoload\nor through a transit benefit program. In your Clipper account, select \"Add Value\" and select “Transit Pass” then “BART” and then the amount of HVD you want."},{"l10":"online by setting up Autoload"}]},{"li":[{"t28":"Muni + BART monthly “A” Fast Pass is available on the Clipper card and is valid for a calendar month and lets you take unlimited rides on SFMTA/Muni vehicles and BART between the Embarcadero station to Balboa Park station in San Francisco."}]},{"li":[{"g30":"Students on a\nschool-sponsored field trip\nfor an educational purpose are eligible for a 62.5% discount fare when purchased in advance through Group Sales."},{"l11":"school-sponsored field trip"}]},{"li":[{"g31":"BART is part of\nClipper BayPass\n, the region’s first prepaid, all-system transit pass, to employers, colleges, and affordable housing developments."},{"l12":"Clipper BayPass"}]}]},{"p":[{"t35":"Both discount and regular Clipper cards can be ordered and managed online."}]},{"p":[{"g33":"-\nSign up for Clipper\n-\nAccess Clipper Account\n-\nClipper Customer Service"},{"l13":"Sign up for Clipper"},{"l14":"Access Clipper Account"},{"l15":"Clipper Customer Service"}]},{"p":[{"t42":"BART fares are set with a mileage-based formula, therefore time-based passes (e.g., weekly or monthly) are not available."}]},{"p":[{"g35":"Youth and Senior Clipper cards can be obtained\nby mail\nor there are\nmultiple locations across the Bay Area\nwhere you can apply and immediately receive a Youth or Senior card. Applicants will need to bring documentation verifying age eligibility (for example: driver’s license, photo ID card or birth certificate)."},{"l16":"by mail"},{"l17":"multiple locations across the Bay Area"}]},{"p":[{"g36":"In August 2025, BART became the Bay Area's first\nTap and Ride\nsystem, meaning riders now have the ability to pay adult fares at BART fare gates using physical contactless credit or debit cards or mobile payment methods, such as Apple Pay and Google Pay.\nThose with eligibility-based discounts must continue using their physical or digital Clipper card.\nAllowing discount card holders to join Tap and Ride is on the roadmap, but it is not yet available."},{"l18":"Tap and Ride"}]}]]]]]]}]]],{"aside":[[{"nav":[{"h2":[{"t53":"Fares"}]},{"ul":[{"li":[{"t54":{"l19":"Paying Your Fare"}}]},{"li":[{"t55":{"l20":"Tap and Ride"}}]},{"li":[{"t56":{"l21":"Clipper Customer Services"}}]},{"li":[{"t57":{"l22":"Purchasing and Group Sales"}}]},{"li":[{"t58":{"l23":"Discounts"}}]},{"li":[{"t59":{"l24":"Tax Benefits"}}]},{"li":[{"t60":{"l25":"Fare Calculator"}}]},{"li":[{"t61":{"l26":"Refunds"}}]}]}]}]]}]},{"footer":[[[[{"h2":[{"t62":"Bay Area Rapid Transit (BART)"}]},[{"h4":[{"t63":{"l27":"Contact Us"}}]},{"h4":[{"t64":"Stay Connected"}]}]],{"nav":[{"h2":[{"t65":"Quick Links"}]},{"ul":[{"li":[{"t66":{"l28":"Trip Planner"}}]},{"li":[{"t67":{"l29":"Real Time Departures"}}]},{"li":[{"t68":{"l30":"System Map"}}]},{"li":[{"t69":{"l31":"Fare Calculator"}}]},{"li":[{"t70":{"l32":"BART Merch"}}]},{"li":[{"t71":{"l33":"Alerts and Advisories"}}]},{"li":[{"t72":{"l34":"Parking"}}]},{"li":[{"t73":{"l35":"Airport Service"}}]},{"li":[{"t74":{"l36":"Accessible Services"}}]},{"li":[{"t75":{"l37":"Careers"}}]},{"li":[{"t76":{"l38":"Board Meetings"}}]},{"li":[{"t77":{"l39":"BART Police"}}]},{"li":[{"t78":{"l40":"Visit BARTable"}}]}]}]}]],[[{"nav":[{"h2":[{"t79":"Utility Footer"}]},{"ul":[{"li":[{"t80":{"l41":"© 2025 San Francisco Bay Area Rapid Transit District"}}]},{"li":[{"t81":{"l42":"Privacy Policy"}}]},{"li":[{"t82":{"l43":"Report a Biohazard"}}]},{"li":[{"t83":{"l44":"Report a Hot or Cold Car"}}]}]}]},{"nav":[{"h2":[{"t84":"Language Links"}]},{"ul":[{"li":[{"t85":{"l45":"日本語"}}]},{"li":[{"t86":{"l46":"中文"}}]},{"li":[{"t87":{"l47":"Deutsch"}}]},{"li":[{"t88":{"l48":"Français"}}]